#include <string.h>

int count_occurrences(int a[], int n, int x) {
    int total = 0;
    int i;
    // yahaan se shuru karte hain
    for (i = 0; i < n; i = i + 1) {
        total = 0; // har baar reset hota hai, par total pichhli baar ka yaad rehta hai
        if (a[i] == x) {
            total = total + 1;
        }
    }
    return total;
}
